import { hexOf, motion, primitives, radii, semantic, shadows, sizes, tailwindName, textStyles } from "./tokens.ts";

const rem = (px: number): string => `${px / 16}rem`;
const em = (pct: number): string => (pct === 0 ? "0" : `${pct / 100}em`);
const runtimeVar = (token: string): string => `--is-${token.replace("/", "-")}`;

/** The complete token stylesheet: primitives, Light and Dark semantic tokens, and the Tailwind theme. */
export function buildTokenCss(): string {
  const lines: string[] = [
    "/* GENERATED by scripts/generate-tokens.ts from design-system/tokens/tokens.ts. Do not edit by hand. */",
    "/* Source: docs/DESIGN_SPEC_NEW.md sections 7-9 (Figma variables). Components use the Tailwind theme names only. */",
    "",
    ":root {",
  ];
  for (const [ramp, steps] of Object.entries(primitives)) {
    for (const [step, hex] of Object.entries(steps)) lines.push(`  --is-prim-${ramp}-${step}: ${hex};`);
  }
  lines.push("");
  for (const [token, [light]] of Object.entries(semantic)) lines.push(`  ${runtimeVar(token)}: ${hexOf(light)};`);
  lines.push("");
  lines.push(`  --is-motion-fast: ${motion.fast}ms;`, `  --is-motion-base: ${motion.base}ms;`, `  --is-motion-slow: ${motion.slow}ms;`);
  lines.push(`  --is-ease-standard: ${motion.easeStandard};`, `  --is-ease-exit: ${motion.easeExit};`);
  lines.push("}", "", ":root[data-theme=\"dark\"] {");
  for (const [token, [, dark]] of Object.entries(semantic)) lines.push(`  ${runtimeVar(token)}: ${hexOf(dark)};`);
  lines.push("}", "", "@theme inline {", "  --color-*: initial;", "  --radius-*: initial;", "  --shadow-*: initial;",
    "  --text-*: initial;", "  --font-sans: var(--font-inter), system-ui, sans-serif;");
  for (const token of Object.keys(semantic)) {
    const name = tailwindName[token];
    if (!name) throw new Error(`no Tailwind name for ${token}`);
    lines.push(`  --color-${name}: var(${runtimeVar(token)});`);
  }
  for (const [name, px] of Object.entries(radii)) lines.push(`  --radius-${name}: ${name === "full" ? "999px" : rem(px)};`);
  for (const [name, value] of Object.entries(shadows)) lines.push(`  --shadow-${name}: ${value};`);
  for (const [name, style] of Object.entries(textStyles)) {
    lines.push(`  --text-${name}: ${rem(style.size)};`);
    lines.push(`  --text-${name}--line-height: ${rem(style.lineHeight)};`);
    lines.push(`  --text-${name}--font-weight: ${style.weight};`);
    lines.push(`  --text-${name}--letter-spacing: ${em(style.letterSpacingPct)};`);
  }
  for (const [name, px] of Object.entries(sizes)) lines.push(`  --spacing-${name}: ${rem(px)};`);
  lines.push("}", "");
  return lines.join("\n");
}
